local PaperCuttingMachineMaker = {}
local PRODUCTS = {
    simple_wood_paper_cutting = { name = "Preprost leseni papirni reznik", woodCost = 4, ironCost = 1, time = 4, cost = 150, science = 20, happiness = 1, description = "Preprost leseni papirni reznik za rezanje papirja." },
    iron_blade_paper_cutting = { name = "Železnorezni papirni reznik", woodCost = 4, ironCost = 2, time = 7, cost = 380, science = 32, happiness = 2, prestige = 2, description = "Železnorezni papirni reznik za trgovce." },
    silver_geared_paper_cutting = { name = "Srebrnozobčan papirni reznik", woodCost = 4, silverCost = 1, ironCost = 2, time = 10, cost = 880, science = 48, happiness = 2, prestige = 6, description = "Srebrnozobčan papirni reznik za plemiče." },
    gold_trimmed_paper_cutting = { name = "Zlatookrasni papirni reznik", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, time = 14, cost = 2000, science = 62, happiness = 3, prestige = 14, description = "Zlatookrasni papirni reznik za visoke plemiče." },
    jewel_set_paper_cutting = { name = "Draguljasta papirni reznik", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, jewelCost = 1, time = 18, cost = 4400, science = 78, happiness = 5, prestige = 27, description = "Papirni reznik z draguljem za visoko plemstvo." },
    royal_grand_paper_cutting = { name = "Kraljevski veliki papirni reznik", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 9500, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski papirni reznik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    paper_cutting_workshop = { name = "Papirna rezna delavnica", cost = { gold = 280, wood = 160, stone = 140, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    printing_loft = { name = "Tiskarska podstrešje", cost = { gold = 1000, wood = 320, stone = 280, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_cutting_atelier = { name = "Mojstrski rezni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_printing_palace = { name = "Kraljevska tiskarska palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
PaperCuttingMachineMaker.woodStock = 20; PaperCuttingMachineMaker.ironStock = 12; PaperCuttingMachineMaker.silverStock = 6; PaperCuttingMachineMaker.goldStock = 6; PaperCuttingMachineMaker.jewelStock = 4; PaperCuttingMachineMaker.pearlStock = 4
PaperCuttingMachineMaker.productStock = {}; PaperCuttingMachineMaker.buildings = {}; PaperCuttingMachineMaker.maker = nil; PaperCuttingMachineMaker.activeMaking = {}; PaperCuttingMachineMaker.totalProducts = 0; PaperCuttingMachineMaker.dayTimer = 0
function PaperCuttingMachineMaker.init() PaperCuttingMachineMaker.woodStock=20; PaperCuttingMachineMaker.ironStock=12; PaperCuttingMachineMaker.silverStock=6; PaperCuttingMachineMaker.goldStock=6; PaperCuttingMachineMaker.jewelStock=4; PaperCuttingMachineMaker.pearlStock=4; PaperCuttingMachineMaker.productStock={}; PaperCuttingMachineMaker.buildings={}; PaperCuttingMachineMaker.maker=nil; PaperCuttingMachineMaker.activeMaking={}; PaperCuttingMachineMaker.totalProducts=0; PaperCuttingMachineMaker.dayTimer=0; print("[PaperCuttingMachineMaker] Royal Paper Cutting Machine Maker System initialized (6 products, 4 buildings)") end
function PaperCuttingMachineMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PaperCuttingMachineMaker.maker={name=n or ("Papirni rezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Papirni rezar najet: %s (spretnost: %d)",PaperCuttingMachineMaker.maker.name,s),"success") end; return true end
function PaperCuttingMachineMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PaperCuttingMachineMaker.build(id) local ok,e=PaperCuttingMachineMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PaperCuttingMachineMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PaperCuttingMachineMaker.getQualityBonus() local b=0; for _,bd in ipairs(PaperCuttingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PaperCuttingMachineMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PaperCuttingMachineMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PaperCuttingMachineMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and PaperCuttingMachineMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PaperCuttingMachineMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PaperCuttingMachineMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PaperCuttingMachineMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PaperCuttingMachineMaker.buildings==0 then return false,"Potrebna papirna rezna delavnica" end; if not PaperCuttingMachineMaker.maker then return false,"Potreben papirni rezar" end; return true end
function PaperCuttingMachineMaker.make(pt,qty) qty=qty or 1; local ok,e=PaperCuttingMachineMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PaperCuttingMachineMaker.woodStock=PaperCuttingMachineMaker.woodStock-d.woodCost*qty end; if d.ironCost then PaperCuttingMachineMaker.ironStock=PaperCuttingMachineMaker.ironStock-d.ironCost*qty end; if d.silverCost then PaperCuttingMachineMaker.silverStock=PaperCuttingMachineMaker.silverStock-d.silverCost*qty end; if d.goldCost then PaperCuttingMachineMaker.goldStock=PaperCuttingMachineMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PaperCuttingMachineMaker.jewelStock=PaperCuttingMachineMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PaperCuttingMachineMaker.pearlStock=PaperCuttingMachineMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PaperCuttingMachineMaker.maker then t=math.max(1,t-math.floor(PaperCuttingMachineMaker.maker.skill/13)) end; table.insert(PaperCuttingMachineMaker.activeMaking,{id="papercuttingmachine_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PaperCuttingMachineMaker.completeMaking(m) local q=1.0+(PaperCuttingMachineMaker.getQualityBonus()/100); if PaperCuttingMachineMaker.maker then q=q+(PaperCuttingMachineMaker.maker.skill/140) end; q=math.min(2.5,q); PaperCuttingMachineMaker.productStock[m.productType]=(PaperCuttingMachineMaker.productStock[m.productType] or 0)+m.quantity; PaperCuttingMachineMaker.totalProducts=PaperCuttingMachineMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PaperCuttingMachineMaker.maker then PaperCuttingMachineMaker.maker.itemsMade=PaperCuttingMachineMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PaperCuttingMachineMaker.maker.skill=math.min(100,PaperCuttingMachineMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Papirni reznik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"papercuttingmachine.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function PaperCuttingMachineMaker.update(dt) if not _G.state then return end; PaperCuttingMachineMaker.dayTimer=PaperCuttingMachineMaker.dayTimer+dt; if PaperCuttingMachineMaker.dayTimer>=30 then PaperCuttingMachineMaker.dayTimer=0; for i=#PaperCuttingMachineMaker.activeMaking,1,-1 do local m=PaperCuttingMachineMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PaperCuttingMachineMaker.completeMaking(m); table.remove(PaperCuttingMachineMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PaperCuttingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PaperCuttingMachineMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PaperCuttingMachineMaker.getStats() return {woodStock=PaperCuttingMachineMaker.woodStock,ironStock=PaperCuttingMachineMaker.ironStock,silverStock=PaperCuttingMachineMaker.silverStock,goldStock=PaperCuttingMachineMaker.goldStock,jewelStock=PaperCuttingMachineMaker.jewelStock,pearlStock=PaperCuttingMachineMaker.pearlStock,productStock=PaperCuttingMachineMaker.productStock,numBuildings=#PaperCuttingMachineMaker.buildings,hasMaker=PaperCuttingMachineMaker.maker~=nil,makerName=PaperCuttingMachineMaker.maker and PaperCuttingMachineMaker.maker.name or "—",makerSkill=PaperCuttingMachineMaker.maker and PaperCuttingMachineMaker.maker.skill or 0,activeMaking=#PaperCuttingMachineMaker.activeMaking,totalProducts=PaperCuttingMachineMaker.totalProducts} end
return PaperCuttingMachineMaker
